  asm volatile("{\n.reg .pred p, q;\n.reg .b32 r;\nelect.sync r|p, 0xffffffff;\nsetp.ne.b32 q, %4, 0;\n@p tcgen05.mma.cta_group::1.kind::f16 [%0], %1, %2, %3, q;\n}"::"r"(dt),"l"(a),"l"(b),"r"(id),"r"(acc):"memory"); }
__device__ __forceinline__ void commit(u32 bar){
  asm volatile("{\n.reg .pred p;\n.reg .b32 r;\nelect.sync r|p, 0xffffffff;\n@p tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];\n}"::"r"(bar):"memory"); }
__device__ __forceinline__ void fa(){ asm volatile("tcgen05.fence::after_thread_sync;":::"memory"); }
__device__ __forceinline__ void fb(){ asm volatile("tcgen05.fence::before_thread_sync;":::"memory"); }
__device__ __forceinline__ u32 pk(float lo, float hi){ u32 r; asm("cvt.rn.f16x2.f32 %0, %1, %2;":"=r"(r):"f"(hi),"f"(lo)); return r; }
__device__ __forceinline__ u16 f2h(float x){ u16 r; asm("cvt.rn.f16.f32 %0, %1;":"=h"(r):"f"(x)); return r; }
__device__ __forceinline__ float h2f(u16 x){ float r; asm("cvt.f32.f16 %0, %1;":"=f"(r):"h"(x)); return r; }
__device__ __forceinline__ u64 gtime(){ u64 t; asm volatile("mov.u64 %0, %%globaltimer;":"=l"(t)); return t; }
__device__ __forceinline__ float4 lds4(u32 a){ float4 v; asm volatile("ld.shared.v4.f32 {%0,%1,%2,%3}, [%4];":"=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w):"r"(a)); return v; }
__device__ __forceinline__ void wbar(){ asm volatile("bar.sync 1, 512;":::"memory"); }

extern "C" __global__ void __launch_bounds__(576,1)
tconv(const u64* __restrict__ tmap, const float* __restrict__ dww, const float* __restrict__ dwb,
      u16* __restrict__ d16, int B, int C, int dstride, unsigned long long* dbg)
{
  extern __shared__ __align__(1024) unsigned char smraw[];
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const u32 sraw = su32(smraw);
  const u32 sbase = (sraw + 1023u) & ~1023u;
  unsigned char* sm = smraw + (sbase - sraw);
  const u32 aA = sbase, aT = sbase + OFF_T, aO = sbase + OFF_O, aS = sbase + OFF_S, aBar = sbase + OFF_BAR;
#define FULL(s) (aBar + 8u*(s))
#define EMPTY(s) (aBar + 8u*(NSLOT + (s)))
#define AREADY(b) (aBar + 8u*(2*NSLOT + (b)))
#define MDONE(b) (aBar + 8u*(2*NSLOT + 2 + (b)))
#define AFREE(b) (aBar + 8u*(2*NSLOT + 4 + (b)))
  volatile u32* tslot = (volatile u32*)(sm + OFF_BAR + NBAR*8);
  const long long PL = (long long)B*C;
  const int G = gridDim.x;
  const long long q0 = PL*blockIdx.x/G, q1 = PL*(blockIdx.x+1)/G;
  if (tid == 0) {
    for (int s=0;s<NSLOT;s++){ mbar_init(FULL(s),1); mbar_init(EMPTY(s),1);}
    for (int b=0;b<2;b++){ mbar_init(AREADY(b),16); mbar_init(MDONE(b),1); mbar_init(AFREE(b),16);}
    asm volatile("fence.mbarrier_init.release.cluster;");
  }
  for (int i = tid; i < TBYTES/16; i += 576) asm volatile("st.shared.v4.u32 [%0], {%1,%1,%1,%1};"::"r"(aT+16u*i),"r"(0u));
  if (warp == 17) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;"::"r"(su32((const void*)tslot)),"r"(256));
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;");
  }
  asm volatile("fence.proxy.async.shared::cta;":::"memory");
  fb();
  __syncthreads();
  fa();
  const u32 tbase = *tslot;
  const u64 t0 = gtime();

  if (warp == 16) {
#ifndef NOLOAD
    if (lane == 0) {
      u32 gb = 0; long long q = q0;
      while (q < q1) {
        const int c = (int)(q / B), b0 = (int)(q - (long long)c*B);
        const int n = (int)min((long long)(B - b0), q1 - q);
        const int T = (n*PP + 127) >> 7;
        for (int u = 0; u <= 16*T; u++, gb++) {
          const u32 slot = gb % NSLOT;
          if (gb >= NSLOT) mbar_wait(EMPTY(slot), ((gb/NSLOT) - 1) & 1);
          const int r0 = 8*u; const int k = r0 / PP; const int h0 = r0 - k*PP - 3;
#ifdef ALIGNED
          if (k < n) { mbar_expect(FULL(slot), BOXB); tma3d(aS + slot*BOXB, tmap, 0, h0, (b0+k)*C + c, FULL(slot)); }
#else
          if (k < n) { mbar_expect(FULL(slot), BOXB); tma3d(aS + slot*BOXB, tmap, -4, h0, (b0+k)*C + c, FULL(slot)); }
#endif
          else mbar_arrive(FULL(slot));
        }
        q += n;
      }
    }
#endif
  } else if (warp == 17) {
    const u32 idesc = (1u<<4) | ((u32)(NN>>3) << 17) | ((u32)(128>>4) << 24);
    int g = 0; long long q = q0;
    const u64 c0 = clock64();
    while (q < q1) {
      const int c = (int)(q / B), b0 = (int)(q - (long long)c*B);
      const int n = (int)min((long long)(B - b0), q1 - q);
      const int T = (n*PP + 127) >> 7;
      for (int t = 0; t < T; t++, g++) {
        const int buf = g & 1;
        mbar_wait(AREADY(buf), (g>>1)&1);
        if (g >= 2) mbar_wait(AFREE(buf), ((g-2)>>1)&1);
        fa();
        const u32 aAb = aA + buf*ABYTES; const u32 dt = tbase + buf*128;
#ifndef NOMMA
#pragma unroll
        for (int i = 0; i < 7; i++)
#pragma unroll
          for (int kk = 0; kk < KS; kk++) {
            const u64 ad = mdesc(aAb + 2*kk*LBOA + i*16, LBOA, 128);
            const u64 bd = mdesc(aT + i*TROWB + 2*kk*128, 128, 128);
            mma(dt, ad, bd, idesc, (i|kk) != 0);
#if HILO
            mma(dt, ad, bd + (u64)(TB1>>4), idesc, 1);
#endif
          }
#endif
        commit(MDONE(buf));
      }
      q += n;
    }
    if (g > 0) mbar_wait(MDONE((g-1)&1), ((g-1)>>1)&1);
    const u64 c1 = clock64(), t1 = gtime();
    if (lane == 0) { dbg[blockIdx.x*4+0]=c1-c0; dbg[blockIdx.x*4+1]=t1-t0; dbg[blockIdx.x*4+2]=g; }
  } else {
    const int qd = warp & 3, cgp = warp >> 2; const int n0 = cgp*NC;
    u32 gb = 0; int g = 0; long long q = q0;
    int pc=0, pb0=0, pn=0, pt=0;
    auto epi = [&](int gg, int c_, int b0_, int n_, int t_) {
      const int bf = gg & 1;
      mbar_wait(MDONE(bf), (gg>>1)&1);
      fa();
      u32 v[NC];
      const u32 ta = tbase + ((u32)(32*qd) << 16) + bf*128 + n0;
#pragma unroll
      for (int j = 0; j < NC; j += 4)
        asm volatile("tcgen05.ld.sync.aligned.32x32b.x4.b32 {%0,%1,%2,%3}, [%4];":"=r"(v[j]),"=r"(v[j+1]),"=r"(v[j+2]),"=r"(v[j+3]):"r"(ta+j));
      asm volatile("tcgen05.wait::ld.sync.aligned;":::"memory");
      fb(); __syncwarp();
      if (lane == 0) mbar_arrive(AFREE(bf));
      const int m = 32*qd + lane; const int s = 128*t_ + m; const int k = s / PP, h = s - k*PP;
      const float bias = __ldg(dwb + c_);
      if (tid == 0) asm volatile("cp.async.bulk.wait_group.read 0;":::"memory");
      wbar();
      if (k < n_ && h < HH) {
        const u32 dst = aO + m*(WW*2) + (NN - n0 - NC)*2;
#pragma unroll
        for (int jj = 0; jj < NC; jj += 4) {
          const u32 p0 = pk(__uint_as_float(v[NC-1-jj]) + bias, __uint_as_float(v[NC-2-jj]) + bias);
          const u32 p1 = pk(__uint_as_float(v[NC-3-jj]) + bias, __uint_as_float(v[NC-4-jj]) + bias);
          asm volatile("st.shared.v2.u32 [%0], {%1,%2};"::"r"(dst + jj*2),"r"(p0),"r"(p1));
        }
      }
      asm volatile("fence.proxy.async.shared::cta;":::"memory");
      wbar();
#ifndef NOSTOREX
      if (tid == 0) {
        const int s0 = 128*t_;
        for (int kk = s0 / PP; kk <= (s0 + 127) / PP && kk < n_; kk++) {
          const int hlo = max(0, s0 - kk*PP), hhi = min(HH, s0 + 128 - kk*PP);
          if (hhi > hlo) {
            const u32 src = aO + (kk*PP + hlo - s0)*(WW*2);
            u16* dstg = d16 + (long long)c_*dstride + (long long)(b0_+kk)*HWW + (long long)hlo*WW;
            asm volatile("cp.async.bulk.global.shared::cta.bulk_group [%0], [%1], %2;"::"l"(dstg),"r"(src),"r"((u32)((hhi-hlo)*WW*2)):"memory");
          }
        }
        asm volatile("cp.async.bulk.commit_group;":::"memory");
      }
#endif
    };
    while (q < q1) {
      const int c = (int)(q / B), b0 = (int)(q - (long long)c*B);
      const int n = (int)min((long long)(B - b0), q1 - q);
      const int T = (n*PP + 127) >> 7;
      if (g > 0) mbar_wait(MDONE((g-1)&1), ((g-1)>>1)&1);
      for (int idx = tid; idx < 7*(1+HILO)*NBND*64; idx += 512) {
        const int e = idx & 7, r = (idx>>3)&7; int rest = idx >> 6;
        const int Di = rest % NBND; rest /= NBND; const int i = rest % 7, hl = rest / 7;
        const int D = DLO + Di; const int j = 8*D + e + r - NN;
        const float tv = (j>=0 && j<=6) ? __ldg(dww + c*49 + i*7 + j) : 0.f;
        u16 hb = f2h(tv); if (hl) hb = f2h(tv - h2f(hb));
        asm volatile("st.shared.u16 [%0], %1;"::"r"(aT + hl*TB1 + i*TROWB + D*128 + r*16 + e*2),"h"(hb));
      }
      for (int t = 0; t < T; t++, g++) {
        const int buf = g & 1;
        const u32 aAb = aA + buf*ABYTES;
#ifndef NOLOAD
        for (int jj = 0; jj < (warp == 0 ? 2 : 1); jj++) {
          const int j = (jj == 0) ? warp : 16;
          const int u = 16*t + j; const u32 bx = gb + u; const u32 slot = bx % NSLOT;
          mbar_wait(FULL(slot), (bx/NSLOT)&1);
          const int rr = lane & 7; const int a = 8*j + rr;
          const u32 src = aS + slot*BOXB + rr*(BW*4);
          for (int qc = lane >> 3; qc < KC; qc += 4) {
            float4 xa = make_float4(0.f,0.f,0.f,0.f), xb = xa;
#ifdef ALIGNED
            if (qc >= 1 && 8*qc - 4 < WW) xa = lds4(src + (8*qc-4)*4);
            if (8*qc < WW) xb = lds4(src + 8*qc*4);
#else
            if (8*qc + 8 <= BW) { xa = lds4(src + qc*32); xb = lds4(src + qc*32 + 16); }
#endif
            asm volatile("st.shared.v4.u32 [%0], {%1,%2,%3,%4};"::"r"(aAb + qc*LBOA + a*16),"r"(pk(xa.x,xa.y)),"r"(pk(xa.z,xa.w)),"r"(pk(xb.x,xb.y)),"r"(pk(xb.z,xb.w)));
          }
          __syncwarp();
          if (lane == 0 && (j != 16 || t == T-1)) mbar_arrive(EMPTY(slot));
        }
#endif
        asm volatile("fence.proxy.async.shared::cta;":::"memory");
        __syncwarp();
        if (lane == 0) mbar_arrive(AREADY(buf));
        if (g > 0) epi(g-1, pc, pb0, pn, pt);
        pc=c; pb0=b0; pn=n; pt=t;
      }
      gb += 16*T+1; q += n;
    }
    if (g > 0) epi(g-1, pc, pb0, pn, pt);
    if (tid == 0) asm volatile("cp.async.bulk.wait_group 0;":::"memory");
  }
  fb();
  __syncthreads();
  if (warp == 17) { fa(); asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;"::"r"(tbase),"r"(256)); }
}
'''
name,v=sys.argv[1],sys.argv[2]
