B,C,H,W,N,KS,P,HILO=CFG[name]
AL='ALIGNED' in v
BW=W if AL else W+8
def smem_bytes(NSLOT):
    KC=2*KS; ABY=KC*137*16; TD=KC+N//8-1; DLO=((N-14)+7)//8; DHI=(N+6)//8; O=max(TD-DLO,DHI+1)
    TB=(6*O+TD)*128*(1+HILO); OFFO=(2*ABY+TB+127)//128*128
    return OFFO+128*W*2+NSLOT*8*BW*4+(2*NSLOT+6)*8+16+1024
