    cu.CUtensorMapInterleave.CU_TENSOR_MAP_INTERLEAVE_NONE,cu.CUtensorMapSwizzle.CU_TENSOR_MAP_SWIZZLE_NONE,
    cu.CUtensorMapL2promotion.CU_TENSOR_MAP_L2_PROMOTION_L2_256B,cu.CUtensorMapFloatOOBfill.CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE)
tm=torch.frombuffer(bytearray(ctypes.string_at(int(tmo.getPtr()),128)),dtype=torch.uint8).cuda()
