        for (int jj = 0; jj < NC; jj += 4) {
          const u32 p0 = pk(__uint_as_float(v[NC-1-jj]) + bias, __uint_as_float(v[NC-2-jj]) + bias);
          const u32 p1 = pk(__uint_as_float(v[NC-3-jj]) + bias, __uint_as_float(v[NC-4-jj]) + bias);
          asm volatile("st.shared.v2.u32 [%0], {%1,%2};"::"r"(dst + jj*2),"r"(p0),"r"(p1));
        }
      }
      asm volatile("fence.proxy.async.shared::cta;":::"memory");
      wbar();
      if (tid == 0) {
        const int s0 = 128*t_;
        for (int kk = s0 / PP; kk <= (s0 + 127) / PP && kk < n_; kk++) {
          const int hlo = max(0, s0 - kk*PP), hhi = min(HH, s0 + 128 - kk*PP);
          if (hhi > hlo) {
            const u32 src = aO + (kk*PP + hlo - s0)*(WW*2);
            u16* dstg = d16 + (long long)c_*dstride + (long long)(b0_+kk)*HWW + (long long)hlo*WW;
            asm volatile("cp.async.bulk.global.shared::cta.bulk_group [%0], [%1], %2;"::"l"(dstg),"r"(src),"r"((u32)((hhi-hlo)*WW*2)):"memory");
          }
        }
        asm volatile("cp.async.bulk.commit_group;":::"memory");
      }
    };
    while (q < q1) {
      const int c = (int)(q / B), b0 = (int)(q - (long long)c*B);
      const int n = (int)min((long long)(B - b0), q1 - q);
      const int T = (n*PP + 127) >> 7;
      if (g > 0) mbar_wait(MDONE((g-1)&1), ((g-1)>>1)&1);
      for (int idx = tid; idx < 7*(1+HILO)*NBND*64; idx += 512) {
        const int e = idx & 7, r = (idx>>3)&7; int rest = idx >> 6;
        const int Di = rest % NBND; rest /= NBND; const int i = rest % 7, hl = rest / 7;
        const int D = DLO + Di; const int j = 8*D + e + r - NN;
        const float tv = (j>=0 && j<=6) ? __ldg(dww + c*49 + i*7 + j) : 0.f;
        u16 hb = f2h(tv); if (hl) hb = f2h(tv - h2f(hb));
        asm volatile("st.shared.u16 [%0], %1;"::"r"(aT + hl*TB1 + i*TROWB + D*128 + r*16 + e*2),"h"(hb));
      }
      for (int t = 0; t < T; t++, g++) {
        const int buf = g & 1;
        const u32 aAb = aA + buf*ABYTES;
        for (int jj = 0; jj < (warp == 0 ? 2 : 1); jj++) {
          const int j = (jj == 0) ? warp : 16;
          const int u = 16*t + j; const u32 bx = gb + u; const u32 slot = bx % NSLOT;
          mbar_wait(FULL(slot), (bx/NSLOT)&1);
          const int rr = lane & 7; const int a = 8*j + rr;
          const u32 src = aS + slot*BOXB + rr*(BW*4);
          for (int qc = lane >> 3; qc < KC; qc += 4) {
            float4 xa = make_float4(0.f,0.f,0.f,0.f), xb = xa;
            if (8*qc + 8 <= BW) { xa = lds4(src + qc*32); xb = lds4(src + qc*32 + 16); }
            asm volatile("st.shared.v4.u32 [%0], {%1,%2,%3,%4};"::"r"(aAb + qc*LBOA + a*16),"r"(pk(xa.x,xa.y)),"r"(pk(xa.z,xa.w)),"r"(pk(xb.x,xb.y)),"r"(pk(xb.z,xb.w)));
          }
          __syncwarp();
          if (lane == 0 && (j != 16 || t == T-1)) mbar_arrive(EMPTY(slot));
        }
        asm volatile("fence.proxy.async.shared::cta;":::"memory");
        __syncwarp();
        if (lane == 0) mbar_arrive(AREADY(buf));
        if (g > 0) epi(g-1, pc, pb0, pn, pt);
        pc=c; pb0=b0; pn=n; pt=t;
